import{_ as p,a0 as o,w as d,s as r,I as a,x as n,a1 as l,A as t,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"通過這個簡單的遊戲學習 Tcl/Tk 和 Wish | LCTT x X-CMD","titleTemplate":false,"description":"通過這個簡單的遊戲學習 Tcl/Tk 和 Wish | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過這個簡單的遊戲學習 Tcl/Tk 和 Wish | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過這個簡單的遊戲學習 Tcl/Tk 和 Wish | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230424.3 ⭐️⭐️ Learn TclTk and Wish with this simple game","title":"通過這個簡單的遊戲學習 Tcl/Tk 和 Wish","tag":"202309","desc":""},"relativePath":"202309/20230424.3 ⭐️⭐️ Learn TclTk and Wish with this simple game.md","filePath":"[post].md"}'),u={name:"202309/20230424.3 ⭐️⭐️ Learn TclTk and Wish with this simple game.md"};function g(h,s,c,k,b,T){const e=o("Link");return d(),r("div",null,[s[39]||(s[39]=a("h1",{id:"通過這個簡單的遊戲學習-tcl-tk-和-wish",tabindex:"-1"},[n("通過這個簡單的遊戲學習 Tcl/Tk 和 Wish "),a("a",{class:"header-anchor",href:"#通過這個簡單的遊戲學習-tcl-tk-和-wish","aria-label":"Permalink to “通過這個簡單的遊戲學習 Tcl/Tk 和 Wish”"},"​")],-1)),s[40]||(s[40]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202309/07/231710i7u72ttuzlt4thhr.jpg",alt:""})],-1)),s[41]||(s[41]=a("blockquote",null,[a("p",null,"以下是一個簡單的編程項目，能夠幫助你開始學習 Tcl/Tk。")],-1)),s[42]||(s[42]=a("p",null,"探索 Tcl/Tk 的基礎構造，包括用户輸入、輸出、變量、條件評估、簡單函數和基礎事件驅動編程。",-1)),a("p",null,[s[2]||(s[2]=n("我寫這篇文章的初衷源於我想更深入地利用基於 Tcl 的 Expect。這讓我寫下了以下兩篇文章：",-1)),l(e,{href:"https://opensource.com/article/23/2/learn-tcl-writing-simple-game"},{default:t(()=>[...s[0]||(s[0]=[n("通過編寫一個簡單的遊戲學習 Tcl",-1)])]),_:1}),s[3]||(s[3]=n(" 和 ",-1)),l(e,{href:"https://opensource.com/article/23/2/learn-expect-automate-simple-game"},{default:t(()=>[...s[1]||(s[1]=[n("通過編寫一個簡單的遊戲學習 Expect",-1)])]),_:1}),s[4]||(s[4]=n("。",-1))]),a("p",null,[s[6]||(s[6]=n("我進行了一些 ",-1)),l(e,{href:"https://www.redhat.com/en/technologies/management/ansible/what-is-ansible?intcmp=7013a000002qLH8AAM"},{default:t(()=>[...s[5]||(s[5]=[n("Ansible",-1)])]),_:1}),s[7]||(s[7]=n(" 自動化工作，逐漸積累了一些本地腳本。有些腳本我頻繁使用，以至於以下循環操作變得有些煩人：",-1))]),s[43]||(s[43]=a("ul",null,[a("li",null,"打開終端"),a("li",null,[n("使用 "),a("code",null,"cd"),n(" 命令跳轉至合適的目錄")]),a("li",null,"輸入一條帶有若干選項的長命令啓動所需的自動化流程")],-1)),a("p",null,[s[9]||(s[9]=n("我日常使用的是 macOS。實際上我更希望有一個菜單項或者一個圖標，能夠彈出一個簡單的界面接受參數並執行我需要的操作，",-1)),l(e,{href:"https://opensource.com/article/23/2/linux-kde-desktop-ansible"},{default:t(()=>[...s[8]||(s[8]=[n("這就像在 Linux 的 KDE 中一樣",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[44]||(s[44]=i(`<p>經典的 Tcl 類書籍都包含了關於流行的 Tk 擴展的文檔。既然我已經深入研究了這個主題，我嘗試着對其（即 <code>wish</code>）進行編程。</p><p>雖然我並非一名 GUI 或者前端開發者，但我發現 Tcl/Tk 腳本編寫的方式相當直接易懂。我很高興能重新審視這個 UNIX 歷史的古老且穩定的部分，這種技術在現代平台上依然有用且可用。</p><h3 id="安裝-tcl-tk" tabindex="-1">安裝 Tcl/Tk <a class="header-anchor" href="#安裝-tcl-tk" aria-label="Permalink to “安裝 Tcl/Tk”">​</a></h3><p>對於 Linux 系統，你可以按照下面的方式安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tcl</span></span>
<span class="line"><span>$ which wish</span></span>
<span class="line"><span>/bin/wish</span></span></code></pre></div>`,5)),a("p",null,[s[12]||(s[12]=n("而在 macOS 上，你可以通過 ",-1)),l(e,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:t(()=>[...s[11]||(s[11]=[n("Homebrew",-1)])]),_:1}),s[13]||(s[13]=n(" 來安裝最新版的 Tcl/Tk：",-1))]),s[45]||(s[45]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install tcl-tk</span></span>
<span class="line"><span>$ which wish</span></span>
<span class="line"><span>/usr/local/bin/wish</span></span></code></pre></div><h3 id="編程理念" tabindex="-1">編程理念 <a class="header-anchor" href="#編程理念" aria-label="Permalink to “編程理念”">​</a></h3><p>許多編寫遊戲的教程都會介紹到典型的編程語言結構，如循環、條件判斷、變量、函數和過程等等。</p>`,3)),a("p",null,[s[15]||(s[15]=n("在此篇文章中，我想要介紹的是 ",-1)),l(e,{href:"https://developers.redhat.com/topics/event-driven/all?intcmp=7013a000002qLH8AAM"},{default:t(()=>[...s[14]||(s[14]=[n("事件驅動編程",-1)])]),_:1}),s[16]||(s[16]=n("。當你的程序使用事件驅動編程，它會進入一個特殊的內置循環，等待特定的事件發生。當這個特定的事件發生時，相應的代碼就會被觸發，產生預期的結果。",-1))]),s[46]||(s[46]=i(`<p>這些事件可以包括鍵盤輸入、鼠標移動、點擊按鈕、定時器觸發，甚至是任何你的電腦硬件能夠識別的事件（可能來自特殊的設備）。你的程序中的代碼決定了用户看到了什麼，以及程序需要監聽什麼輸入，當這些輸入被接收後程序會怎麼做，然後進入事件循環等待輸入。</p><p>這篇文章的理念並沒有脱離我之前的 Tcl 文章太遠。這裏最大的不同在於用 GUI 設置和用於處理用户輸入的事件循環替代了循環結構。其他的不同則是 GUI 開發需要採取的各種方式來製作一個可用的用户界面。在採用 Tk GUI 開發的時候，你需要了解兩個基礎的概念：<ruby>部件<rt>widget</rt></ruby>和<ruby>幾何管理器<rt>geometry manager</rt></ruby>。</p><p>部件是構成可視化元素的 UI 元素，通過這些元素用户可以與程序進行交互。這其中包括了按鈕、文本區域、標籤和文本輸入框。部件還包括了一些選項選擇，如菜單、複選框、單選按鈕等。最後，部件也包括了其他的可視化元素，如邊框和線性分隔符。</p><p>幾何管理器在放置部件在顯示窗口中的位置上扮演着至關重要的角色。有一些不同的幾何管理器可以供你使用。在這篇文章中，我主要使用了 <code>grid</code> 幾何來讓部件在整齊的行中進行佈局。我會在這篇文章的結尾地方解釋一些幾何管理器的不同之處。</p><h3 id="用-wish-進行猜數字遊戲" tabindex="-1">用 wish 進行猜數字遊戲 <a class="header-anchor" href="#用-wish-進行猜數字遊戲" aria-label="Permalink to “用 wish 進行猜數字遊戲”">​</a></h3><p>這個示例遊戲代碼與我其他文章中的示例有所不同，我將它分解為若干部分以方便解釋。</p><p>首先創建一個基本的可執行腳本 <code>numgame.wish</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch numgame.wish</span></span>
<span class="line"><span>$ chmod 755 numgame.wish</span></span></code></pre></div><p>使用你喜歡的文本編輯器打開此文件，輸入下列代碼的第一部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env wish</span></span>
<span class="line"><span>set LOW 1</span></span>
<span class="line"><span>set HIGH 100</span></span>
<span class="line"><span>set STATUS &quot;&quot;</span></span>
<span class="line"><span>set GUESS &quot;&quot;</span></span>
<span class="line"><span>set num [expr round(rand()*100)]</span></span></code></pre></div><p>第一行定義了該腳本將通過 <code>wish</code> 執行。接下來，創建了幾個全局變量。這裏我使用全部大寫字母定義全局變量，這些變量將綁定到跟蹤這些值的窗口小部件（<code>LOW</code>、<code>HIGH</code>等等）。</p><p>全局變量 <code>num</code> 是遊戲玩家要猜測的隨機數值，這個值是通過 Tcl 的命令執行得到並保存到變量中的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>proc Validate {var} {</span></span>
<span class="line"><span>    if { [string is integer $var] } {</span></span>
<span class="line"><span>        return 1</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這是一個驗證用户輸入的特殊函數，它只接受整數並拒絕其他所有類型的輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>proc check_guess {guess num} {</span></span>
<span class="line"><span>    global STATUS LOW HIGH GUESS</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if { $guess &lt; $LOW } {</span></span>
<span class="line"><span>        set STATUS &quot;What?&quot;</span></span>
<span class="line"><span>    } elseif { $guess &gt; $HIGH } {</span></span>
<span class="line"><span>        set STATUS &quot;Huh?&quot;</span></span>
<span class="line"><span>    } elseif { $guess &lt; $num } {</span></span>
<span class="line"><span>        set STATUS &quot;Too low!&quot;</span></span>
<span class="line"><span>        set LOW $guess</span></span>
<span class="line"><span>    } elseif { $guess &gt; $num } {</span></span>
<span class="line"><span>        set STATUS &quot;Too high!&quot;</span></span>
<span class="line"><span>        set HIGH $guess</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        set LOW $guess</span></span>
<span class="line"><span>        set HIGH $guess</span></span>
<span class="line"><span>        set STATUS &quot;That&#39;s Right!&quot;</span></span>
<span class="line"><span>        destroy .guess .entry</span></span>
<span class="line"><span>        bind all &lt;Return&gt; {.quit invoke}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    set GUESS &quot;&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這是主要的猜數邏輯循環。<code>global</code> 語句讓我們能夠修改在文件開頭創建的全局變量（關於此主題後面將會有更多解釋）。這個條件判斷尋找入力範圍在 1 至 100 之外以及已經被用户猜過的值。有效的猜測和隨機值進行比較。<code>LOW</code> 和 <code>HIGH</code> 的猜測會被追蹤，作為 UI 中的全局變量進行報告。在每一步，全局 <code>STATUS</code> 變量都會被更新，這個狀態信息會自動在 UI 中顯示。</p><p>對於正確的猜測，<code>destroy</code> 語句會移除 “Guess” 按鈕以及輸入窗口，並重新綁定回車鍵，以激活 “Quit” 按鈕。</p><p>最後的語句 <code>set GUESS &quot;&quot;</code> 用於在下一個猜測之前清空輸入窗口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>label .inst -text &quot;Enter a number between: &quot;</span></span>
<span class="line"><span>label .low -textvariable LOW</span></span>
<span class="line"><span>label .dash -text &quot;-&quot;</span></span>
<span class="line"><span>label .high -textvariable HIGH</span></span>
<span class="line"><span>label .status -text &quot;Status:&quot;</span></span>
<span class="line"><span>label .result -textvariable STATUS</span></span>
<span class="line"><span>button .guess -text &quot;Guess&quot; -command { check_guess $GUESS $num }</span></span>
<span class="line"><span>entry .entry -width 3 -relief sunken -bd 2 -textvariable GUESS -validate all \\</span></span>
<span class="line"><span>    -validatecommand { Validate %P }</span></span>
<span class="line"><span>focus .entry</span></span>
<span class="line"><span>button .quit -text &quot;Quit&quot; -command { exit }</span></span>
<span class="line"><span>bind all &lt;Return&gt; {.guess invoke}</span></span></code></pre></div><p>這是設置用户界面的部分。前六個標籤語句在你的 UI 上創建了不同的文本展示元素，<code>-textvariable</code> 選項監控給定的變量，並自動更新標籤的值，這展示了全局變量 <code>LOW</code>、<code>HIGH</code>、<code>STATUS</code> 的綁定。</p><p><code>button</code> 行創建了 “Guess” 和 “Quit” 按鈕， <code>-command</code> 選項設定了當按鈕被按下時要執行的操作。按下 “Guess” 按鈕執行了上面的 <code>check_guess</code> 函數以檢查用户輸入的值。</p><p><code>entry</code> 部件更有趣。它創建了一個三字符寬的輸入框，並將輸入綁定到 <code>GUESS</code> 全局變量。它還通過 <code>-validatecommand</code> 選項設置了驗證，阻止輸入部件接收除數字以外的任何內容。</p><p><code>focus</code> 命令是用户界面的一項改進，使程序啓動時輸入部件處於激活狀態。沒有此命令，你需要先點擊輸入部件才可以輸入。</p><p><code>bind</code> 命令允許你在按下回車鍵時自動點擊 “Guess” 按鈕。如果你記得 <code>check_guess</code> 中的內容，猜測正確之後會重新綁定回車鍵到 “Quit” 按鈕。</p><p>最後，這部分設定了圖形用户界面的佈局：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grid .inst</span></span>
<span class="line"><span>grid .low .dash .high</span></span>
<span class="line"><span>grid .status .result</span></span>
<span class="line"><span>grid .guess .entry</span></span>
<span class="line"><span>grid .quit</span></span></code></pre></div><p><code>grid</code> 幾何管理器被逐步調用，以逐漸構建出預期的用户體驗。它主要設置了五行部件。前三行是顯示不同值的標籤，第四行是 “Guess” 按鈕和 <code>entry</code> 部件，最後是 “Quit” 按鈕。</p><p>程序到此已經初始化完畢，<code>wish</code> shell 進入事件循環，等待用户輸入整數並按下按鈕。基於其在被監視的全局變量中找到的變化，它會更新標籤。</p><p>注意，輸入光標開始就在輸入框中，而且按下回車鍵將調用適當且可用的按鈕。</p><p>這只是一個初級的例子，Tcl/Tk 有許多可以讓間隔、字體、顏色和其他用户界面方面更具有吸引力的選項，這超出了本文中簡單 UI 的示例。</p><p>運行這個應用，你可能會注意到這些部件看起來並不很精緻或現代。這是因為我正在使用原始的經典部件集，它們讓人回憶起 X Windows Motif 的時代。不過，還有一些默認的部件擴展，被稱為主題部件，它們可以讓你的應用程序有更現代、更精緻的外觀和感覺。</p><h3 id="啓動遊戲" tabindex="-1">啓動遊戲！ <a class="header-anchor" href="#啓動遊戲" aria-label="Permalink to “啓動遊戲！”">​</a></h3><p>保存文件之後，在終端中運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./numgame.wish</span></span></code></pre></div><p>在這種情況下，我無法給出控制台的輸出，因此這裏有一個動畫 GIF 來展示如何玩這個遊戲：</p><p><img src="https://opensource.com/sites/default/files/2023-03/numgame-wish.gif" alt="用 Wish 編寫的猜數遊戲"></p><h3 id="進一步瞭解-tcl" tabindex="-1">進一步瞭解 Tcl <a class="header-anchor" href="#進一步瞭解-tcl" aria-label="Permalink to “進一步瞭解 Tcl”">​</a></h3><p>Tcl 支持命名空間的概念，所以在這裏使用的變量並不必須是全局的。你可以把綁定的部件變量組織進不同的命名空間。對於像這樣的簡單程序，可能並不太需要這麼做。但對於更大規模的項目，你可能會考慮這種方法。</p><p><code>proc check_guess</code> 函數體內有一行 <code>global</code> 代碼我之前沒有解釋。在 Tcl 中，所有變量都按值傳遞，函數體內引用的變量的範圍是局部的。在這個情況下，我希望修改的是全局變量，而不是局部範圍的版本。Tcl 提供了許多方法來引用變量，在執行堆棧的更高級別執行代碼。在一些情況下，像這樣的簡單引用可能帶來一些複雜性和錯誤，但是調用堆棧的操作非常有力，允許 Tcl 實現那些在其他語言中實現起來可能較為複雜的新的條件和循環結構。</p>`,39)),a("p",null,[s[18]||(s[18]=n("最後，在這篇文章中，我沒有提到幾何管理器，它們用於以特定的順序展示部件。只有被某種幾何管理器管理的部件才能顯示在屏幕上。grid 管理器相當簡潔，它按照從左到右的方式放置部件。我使用了五個 grid 定義來創建了五行。另外還有兩個幾何管理器：place 和 pack。pack 管理器將部件圍繞窗口邊緣排列，而 place 管理器允許固定部件的位置。除這些幾何管理器外，還有一些特殊的部件，如 ",-1)),s[19]||(s[19]=a("code",null,"canvas",-1)),s[20]||(s[20]=n(" ，",-1)),s[21]||(s[21]=a("code",null,"text",-1)),s[22]||(s[22]=n(" 和 ",-1)),s[23]||(s[23]=a("code",null,"panedwindow",-1)),s[24]||(s[24]=n("，它們可以容納並管理其他部件。你可以在經典的 Tcl/Tk 參考指南，以及 ",-1)),l(e,{href:"https://tcl.tk/man/tcl8.7/TkCmd/index.html"},{default:t(()=>[...s[17]||(s[17]=[n("Tk 命令",-1)])]),_:1}),s[25]||(s[25]=n(" 文檔頁上找到這些部件的全面描述。",-1))]),s[47]||(s[47]=a("h3",{id:"繼續學習編程",tabindex:"-1"},[n("繼續學習編程 "),a("a",{class:"header-anchor",href:"#繼續學習編程","aria-label":"Permalink to “繼續學習編程”"},"​")],-1)),s[48]||(s[48]=a("p",null,"Tcl 和 Tk 提供了一個簡單有效的方法來構建圖形用户界面和事件驅動應用程序。這個簡單的猜數遊戲只是你能用這些工具做到的事情的起點。通過繼續學習和探索 Tcl 和 Tk，你可以打開構建強大且用户友好的應用程序的無數可能性。繼續嘗試，繼續學習，看看你新習得的 Tcl 和 Tk 技能能帶你到哪裏。",-1)),s[49]||(s[49]=a("p",null,[a("em",null,"（題圖：MJ/40621c50-6577-4033-9f3c-8013bd0286f1）")],-1)),s[50]||(s[50]=a("hr",null,null,-1)),a("p",null,[s[27]||(s[27]=n("via: ",-1)),l(e,{href:"https://opensource.com/article/23/4/learn-tcltk-wish-simple-game"},{default:t(()=>[...s[26]||(s[26]=[n("https://opensource.com/article/23/4/learn-tcltk-wish-simple-game",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=n("作者：",-1)),l(e,{href:"https://opensource.com/users/jamesf"},{default:t(()=>[...s[28]||(s[28]=[n("James Farrell",-1)])]),_:1}),s[32]||(s[32]=n(" 選題：",-1)),l(e,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[29]||(s[29]=[n("lkxed",-1)])]),_:1}),s[33]||(s[33]=n(" 譯者：ChatGPT 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[30]||(s[30]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[36]||(s[36]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[34]||(s[34]=[n("LCTT",-1)])]),_:1}),s[37]||(s[37]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...s[35]||(s[35]=[n("Linux中國",-1)])]),_:1}),s[38]||(s[38]=n(" 榮譽推出",-1))])])}const w=p(u,[["render",g]]);export{x as __pageData,w as default};
